function parseIdsTxt(): string[] {
  const root = process.cwd();
  const lines = fs.readFileSync(path.join(root, 'tests/ids.txt'), 'utf8').split('\n');
  let section = '';
  let sectionNo = 0;
  const ids: string[] = [];

  for (const line of lines) {
    const s = line.match(/^(\d+)\)\s+(.*)$/);
    if (s) {
      sectionNo = Number(s[1]);
      section = s[2].trim();
      continue;
    }
    if (!line.startsWith('- ')) continue;
    if (sectionNo < 2) continue;
    if (section.includes('Coverage Usage Rules')) continue;
    if (section.includes('Parameterized Dynamic ID Templates')) continue;

    const id = line.slice(2).trim();
    if (!id) continue;
    if (id.startsWith('Total managed IDs:')) continue;
    if (id.startsWith('Source:')) continue;
    if (id.startsWith('Rule:')) continue;
    if (id.startsWith('This file is')) continue;
    if (id.startsWith('Every test selector')) continue;
    if (id.startsWith('`tests/types.txt`')) continue;
    ids.push(id);
  }

  return [...new Set(ids)].sort();
}

describe('Managed test ID explicit inventory', () => {
  it('contains only unique IDs', () => {
    const arr = [...EXPLICIT_MANAGED_IDS];
    expect(new Set(arr).size).toBe(arr.length);
  });

  it('is fully synchronized with tests/ids.txt', () => {
    const fromFile = parseIdsTxt();
    expect([...EXPLICIT_MANAGED_IDS].sort()).toEqual(fromFile);
  });
});
